import { db } from "file:///F:/hrms/node_backend/src/db/index.js";

async function verify() {
  try {
    const version = await db.all("SELECT VERSION() as v");
    const maxConn = await db.all("SHOW VARIABLES LIKE 'max_connections'");
    const waitTimeout = await db.all("SHOW VARIABLES LIKE 'wait_timeout'");
    const bufferPool = await db.all("SHOW VARIABLES LIKE 'innodb_buffer_pool_size'");
    const currentConns = await db.all("SHOW STATUS LIKE 'Threads_connected'");

    console.log("=== LIVE MYSQL SERVER VARIABLES ===");
    console.log("Version:", version[0]?.v);
    console.log("max_connections:", maxConn[0]?.Value);
    console.log("wait_timeout:", waitTimeout[0]?.Value);
    console.log("innodb_buffer_pool_size:", bufferPool[0]?.Value, `(${Math.round(Number(bufferPool[0]?.Value || 0) / 1024 / 1024)} MB)`);
    console.log("Threads_connected:", currentConns[0]?.Value);

    // Check existing attendance table records for any duplicates or multiple records per user per day
    console.log("\n=== ATTENDANCE DUPLICATE CHECK ===");
    const duplicates = await db.all(`
      SELECT user_id, date, COUNT(*) as count 
      FROM attendance_attendance 
      GROUP BY user_id, date 
      HAVING count > 1
    `);
    console.log("Duplicate (user_id, date) records found in DB:", duplicates.length);
    if (duplicates.length > 0) {
      console.log("Duplicate records:", duplicates);
    }

    const totalAttendance = await db.all("SELECT COUNT(*) as c FROM attendance_attendance");
    console.log("Total attendance records:", totalAttendance[0]?.c);

    // Check attendance sample rows
    const sampleAtt = await db.all("SELECT id, user_id, date, punch_in_time, punch_out_time, status FROM attendance_attendance ORDER BY id DESC LIMIT 5");
    console.log("Recent attendance records:", sampleAtt);

    // Check leave records
    const sampleLeaves = await db.all("SELECT id, user_id, leave_type, from_date, to_date, status FROM leave_leave ORDER BY id DESC LIMIT 5");
    console.log("\n=== LEAVE SAMPLE RECORDS ===");
    console.log("Recent leaves:", sampleLeaves);

  } catch (err) {
    console.error("Verification query error:", err);
  }
  process.exit(0);
}

verify();

